message.content:
{
  "css": ".product-identity {
  padding-top: 24px;
  padding-bottom: 24px;
}

.product-identity .eyebrow {
  font-size: 14px;
  color: #60606a;
  margin-bottom: 8px;
}

.product-identity .title {
  font-size: 22px;
  font-weight: 700;
  line-height: 1.45;
  word-break: keep-all;
  overflow-wrap: anywhere;
}

.product-identity .price-row {
  margin-top: 12px;
}

.product-identity .price {
  display: block;
  font-size: 24px;
  font-weight: 800;
  word-break: keep-all;
}

.product-identity .metadata {
  margin-top: 24px;
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
}

.product-identity .meta-item {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 500;
  color: #555560;
  word-break: keep-all;
}

.product-identity .meta-item img {
  width: 20px;
  height: 20px;
  display: block;
}

.product-identity .description {
  margin-top: 20px;
  font-size: 15px;
  line-height: 1.75;
  word-break: keep-all;
  overflow-wrap: anywhere;
}

@media (min-width: 701px) {
  .product-identity {
    padding-top: 0;
  }

  .product-identity .title {
    font-size: 28px;
  }
}"
}
